/** P1 — the "star ignition" moment on lesson completion. */
export interface ConstellationCelebrationProps {
  seriesSlug: string;
  courseName: string;
  lessonSlug: string;
  lessonLabel: string;
  /** Stars lit in the course AFTER this lesson. */
  litStars: number;
  totalStars: number;
  /** Live current streak as-of now (B-19 derivation). */
  streakDays: number;
  /** True when this lesson completes the course → pulse + longer moment. */
  courseJustCompleted: boolean;
  prefersReducedMotion?: boolean;
}

/** P1 — series-outline full constellation. */
export interface SeriesConstellationProps {
  constellation: ConstellationState;
  isGuest: boolean;
}

/** P1 — hub-card constellation preview (keep light — compact). */
export interface ConstellationPreviewProps {
  constellation: ConstellationState;
  /** Hub stays light: compact preview vs full detail. */
  compact?: boolean;
}

/** P1 — streak chip shown at the lesson-complete beat. */
export interface StreakCounterProps {
  streakDays: number;
  /** Inline vs stat-card treatment. */
  variant?: "inline" | "stat";
}

/** P2 — profile full sky section (aggregate constellations + ladder + feed). */
export interface FullSkySectionProps {
  sky: ProfileSky;
}

/** P2 — guest "locked sky" teaser (pairs with B-09). */
export interface LockedSkyTeaserProps {
  /** e.g. "/login?next=/profile". */
  ctaHref?: string;
}

/** P2 — certificate celebration: constellation completes + reveal. */
export interface CertificateCelebrationProps {
  seriesSlug: string;
  courseName: string;
  constellation: ConstellationState;
  streakDays: number;
}

