/** GET /api/progress/achievement → AchievementStats (P1 pop + hub). */
export type AchievementResponse = { stats: AchievementStats };

/** POST /api/progress/lesson augmentation (no shape change — body unchanged). */
export interface LessonCompletionResponseBody {
  status: "ok" | "error" | "unauthenticated";
  /** Present only when the lesson completes its course. */
  courseJustCompleted?: boolean;
}